    // site whose language is English, comes back as the key itself.
    // {var:1}, {var:2} … and {var} are filled from `vars`, as lang() does.
    // A raw Turkish literal anywhere the operator can read it is a defect;
    // docs/_tools/designer_i18n.php lists them.
    function _sdT(key, vars) {
        var map = (typeof sdDesign !== 'undefined' && sdDesign && sdDesign.i18n) ? sdDesign.i18n : null;
        var out = (map && Object.prototype.hasOwnProperty.call(map, key)) ? String(map[key]) : String(key);
        if (vars !== undefined && vars !== null) {
            var list = Array.isArray(vars) ? vars : [vars];
            out = out.replace(/\{var(?::(\d+))?\}/g, function (m, n) {
                var i = n ? parseInt(n, 10) - 1 : 0;
                return (i >= 0 && i < list.length && list[i] !== undefined && list[i] !== null) ? String(list[i]) : m;
            });
        }
        return out;
    }

