        sharedBadge.innerHTML = '<span class="bi ' + (_isSysWidget ? 'bi-cpu' : 'bi-puzzle-fill') + '"></span> ' + esc(scName || '?');
        tb.appendChild(sharedBadge);

        var tbBtns = doc.createElement('div');
        tbBtns.className = 'sd-tb-btns';

