        '__has_low_stock': 1, '__has_tax': 1, '__has_shipping': 1,
        '__has_offers': 1, '__has_terms': 1, '__is_cancelled': 1,
        '__can_cancel': 1, '__has_timeline': 1, '__has_notes': 1,
