                // Multi-recipient block — only shown when the widget tree does NOT
                // already contain a recipient_loop_area. Single button injects an
                // empty recipient_loop_area into the widget root; designer then
                // drags fields into it.
                var _eoHasRlaScan = false;
                (function _scanRla(n) {
                    if (_eoHasRlaScan || !n) return;
                    if (n.type === 'recipient_loop_area') { _eoHasRlaScan = true; return; }
                    if (Array.isArray(n.children)) n.children.forEach(_scanRla);
                })(_eoTreeObj);
                var _eoRlaRowHtml = '';
                if (!_eoHasRlaScan) {
                    _eoRlaRowHtml = ''
                        + '<div class="sd-prop-row" style="border-top:1px solid #e5e7eb;margin-top:8px;padding-top:8px"><label class="sd-prop-label">' + esc(_sdT('Multi-Recipient Design')) + '</label><div class="sd-prop-control">'
                        +   '<button type="button" class="btn btn-sm btn-outline-success" id="sd-sw-eo-add-recipient-loop" data-sw-id="' + sid + '">'
                        +     '<i class="bi bi-people me-1"></i>' + esc(_sdT('Add a Recipient List Block'))
                        +   '</button>'
                        +   '<div style="font-size:.66rem;color:#888;margin-top:3px">'
                        +     _sdT('Adds a designer template that repeats for every ship_to in a multi-recipient cart. Use the eo_field bindings inside it — <code>shipping_first_name</code>, <code>shipping_last_name</code> and so on — and the server renames each one to <code>shipping_&lt;rid&gt;_*</code> per recipient. Once added, a <strong>Recipient List</strong> element appears at the widget root and you can move it anywhere.')
                        +   '</div>'
                        + '</div></div>';
                } else {
                    _eoRlaRowHtml = ''
                        + '<div class="sd-prop-row" style="border-top:1px solid #e5e7eb;margin-top:8px;padding-top:8px"><label class="sd-prop-label">' + esc(_sdT('Multi-Recipient Design')) + '</label><div class="sd-prop-control">'
                        +   '<div style="font-size:.7rem;color:#0d9488;background:rgba(13,148,136,.08);padding:5px 8px;border-radius:3px;line-height:1.4">'
                        +     '<i class="bi bi-check-circle-fill me-1"></i>'
                        +     _sdT('<strong>The Recipient List block is present.</strong> Select it on the canvas to edit what is inside.')
                        +   '</div>'
                        + '</div></div>';
                }

                var _eoDesignerBody = ''
                    + _eoLayoutWarn
                    + '<div class="sd-prop-row"><label class="sd-prop-label">' + esc(_sdT('Current Sections')) + '</label><div class="sd-prop-control">'
                    +   _eoChecklistHtml
                    + '</div></div>'
                    + '<div class="sd-prop-row"><label class="sd-prop-label">' + esc(_sdT('Layout Template')) + '</label><div class="sd-prop-control">'
                    +   '<button type="button" class="btn btn-sm btn-outline-primary" id="sd-sw-eo-load-default" data-sw-id="' + sid + '">'
                    +     '<i class="bi bi-magic me-1"></i>' + esc(_sdT('Load the Default Layout'))
                    +   '</button>'
                    +   '<div style="font-size:.66rem;color:#888;margin-top:3px">' + _sdT('<strong>Replaces</strong> the current tree with the standard layout that holds every section. This cannot be undone.') + '</div>'
                    + '</div></div>'
                    + _eoRlaRowHtml;
                    // NOTE: the previous "Section Binding (to the selected element)"
