                            // Only what the server honours (pg_cf_url_prefill_values()).
                            var fUrl = _swUrlParamName(f.url_param);
                            if (fUrl && !f.office_use_only && _cfUrlParamApplies(f.lead, f.members)) flags.push('?' + fUrl + '=');
