    // Resolve the regionType of the system widget that contains `node`.
    // Returns one of: 'form_list_view' (default), 'form_item_view',
    // 'catalog_listing', or '' if not in a SW.
    function _getSystemWidgetRegionType(node) {
        var sid = _isInsideSystemWidget(node);
        if (!sid) return '';
        var cached = _sharedCache[sid];
        if (!cached || !cached.system_region_config) return 'form_list_view';
        try {
            var cfg = JSON.parse(cached.system_region_config);
            if (cfg && cfg.regionType === 'catalog_listing')   return 'catalog_listing';
            if (cfg && cfg.regionType === 'catalog_item_view') return 'catalog_item_view';
            if (cfg && cfg.regionType === 'form_item_view')    return 'form_item_view';
            if (cfg && cfg.regionType === 'my_account')        return 'my_account';
            if (cfg && cfg.regionType === 'login_form')        return 'login_form';
            if (cfg && cfg.regionType === 'forgot_password')   return 'forgot_password';
            if (cfg && cfg.regionType === 'search_results')    return 'search_results';
            if (cfg && cfg.regionType === 'registration')      return 'registration';
            if (cfg && cfg.regionType === 'shopping_cart')     return 'shopping_cart';
            if (cfg && cfg.regionType === 'express_order')     return 'express_order';
            if (cfg && cfg.regionType === 'order_view')        return 'order_view';
            if (cfg && cfg.regionType === 'membership')        return 'membership';
            if (cfg && cfg.regionType === 'custom_form')       return 'custom_form';
            if (cfg && cfg.regionType === 'calendar_view')     return 'calendar_view';
            if (cfg && cfg.regionType === 'calendar_event_view') return 'calendar_event_view';
            if (cfg && _SW_ACCOUNT_TYPES[cfg.regionType] === 1) return cfg.regionType;
            if (cfg && cfg.regionType === 'error_page')        return 'error_page';
            // login_region, cart_link, language_switcher: a palette of their own.
            if (cfg && SW_ACCOUNT_TOKEN_PALETTES[cfg.regionType]) return cfg.regionType;
            return 'form_list_view';
        } catch (e) { return 'form_list_view'; }
    }

    // What props on `node` are bindable? Returns an array of {prop, label, kind}
    // where `kind` hints at which field types make sense (text|url|image).
    // Table plumbing — these carry layout, never a value. See the comment at
    // the `text` binding below for why binding data to them is disallowed.
    var SD_STRUCTURAL_TAGS = ['table', 'thead', 'tbody', 'tfoot', 'tr', 'td', 'th', 'caption', 'colgroup', 'col'];
    function _sdIsStructuralTag(tag) {
        return SD_STRUCTURAL_TAGS.indexOf((tag || '').toLowerCase()) !== -1;
    }

    // One-time migration for trees saved before the "bind content, not layout"
    // rule. Walks the tree; whenever a structural tag carries a text/src/href
    // binding, the binding (and the cell's preview text) moves into a <span>
    // added as the cell's first child. The cell keeps its classes, attributes,
    // colspan and alignment — only the value moves.
    //
    // Idempotent: after the move the cell has no binding left, so a second pass
    // finds nothing to do.
    function _sdMigrateStructuralBindings(node) {
        if (!node || typeof node !== 'object') return false;
        var changed = false;

        if (node.type === 'semantic' && node.props && _sdIsStructuralTag(node.props.tag)) {
            var b = node.props._bindings;
            if (b && (b.text || b.src || b.href)) {
                var moved = {};
                ['text', 'src', 'href'].forEach(function (k) {
                    if (b[k]) { moved[k] = b[k]; delete b[k]; }
                });
                // An <img>-style binding needs an <img>; everything else a <span>.
                var innerTag = moved.src ? 'img' : 'span';
                var inner = createNode('semantic', {
                    tag: innerTag,
                    cssClass: '',
                    text: (innerTag === 'span') ? (node.props.text || '') : '',
                    _bindings: moved
                });
                if (innerTag === 'span') node.props.text = '';
                node.children = node.children || [];
                node.children.unshift(inner);
                if (!Object.keys(b).length) delete node.props._bindings;
                changed = true;
            }
        }

        if (node.children && node.children.length) {
            for (var i = 0; i < node.children.length; i++) {
                if (_sdMigrateStructuralBindings(node.children[i])) changed = true;
            }
        }
        return changed;
    }

    function _getBindableProps(node) {
        if (!node) return [];
        var out = [];
        if (node.type === 'content') {
            var ct = node.props && node.props.contentType;
            if (ct === 'heading' || ct === 'paragraph' || ct === 'span') {
                out.push({ prop: 'text', label: _sdT('Text'), kind: 'text' });
            } else if (ct === 'link') {
                out.push({ prop: 'text', label: _sdT('Text'), kind: 'text' });
                out.push({ prop: 'href', label: _sdT('URL'),   kind: 'url'  });
            } else if (ct === 'image') {
                out.push({ prop: 'src',  label: _sdT('Image src'), kind: 'image' });
                out.push({ prop: 'alt',  label: _sdT('Alt text'),  kind: 'text'  });
            } else if (ct === 'icon') {
                // could bind iconName but no real use case yet
            }
        } else if (node.type === 'semantic') {
            var tag = (node.props && node.props.tag || '').toLowerCase();
            if (tag === 'a') {
                out.push({ prop: 'href', label: _sdT('URL'),   kind: 'url'  });
                out.push({ prop: 'text', label: _sdT('Text'), kind: 'text' });
            } else if (tag === 'img') {
                out.push({ prop: 'src',  label: _sdT('Image src'), kind: 'image' });
                out.push({ prop: 'alt',  label: _sdT('Alt text'),  kind: 'text'  });
            } else if (node.props && (node.props.text || (node.props._bindings && node.props._bindings.text))) {
                // A bound element needs no literal text of its own: a <div>
                // bound to a ready-made HTML block (__timeline, __currency_selector)
                // carries only the binding. Keying this on props.text alone
                // left such a binding out of the panel entirely.
                //
                // Structural table tags are LAYOUT, not content. A <td> owns
                // its column, alignment and width; binding the value straight
                // onto it means the designer can't wrap that value in a link,
                // put a badge beside it, or restyle the number alone — and the
                // moment they drop another element into the cell, the binding
                // overwrites it. The value belongs on a span/heading/p/a/img
                // INSIDE the cell, which is what every other binding does.
                //
                // Still offered when a binding is ALREADY set, otherwise trees
                // saved before this rule would carry an invisible binding the
                // designer could neither see nor clear.
                var alreadyBoundText = !!(node.props._bindings && node.props._bindings.text);
                if (!_sdIsStructuralTag(tag) || alreadyBoundText) {
                    out.push({ prop: 'text', label: _sdT('Text'), kind: 'text' });
                }
            }
        } else if (node.type === 'component') {
            // Buttons (btn) — bind text + href
            var ctype = node.props && node.props.componentType;
            if (ctype === 'btn') {
                out.push({ prop: 'text', label: _sdT('Button text'), kind: 'text' });
                out.push({ prop: 'href', label: _sdT('Button URL'),   kind: 'url'  });
            }
        }
        return out;
    }

    // Render the data-binding section for the props panel.
    // Returns '' when the node is NOT inside a system widget OR has no bindable props.
    //
    // The dropdown is composed of three groups:
    //   1. "— No binding —"  (clear binding)
    //   2. Form-specific fields (form_fields rows for the widget's selected form)
    //   3. Built-in tokens (__id, __reference, __timestamp …)
    //   4. "Custom field name…"   (free-text input fallback)
    //
    // If the parent system widget hasn't been bound to a form yet, we show a warning
    // with a hint to pick a form first (the data-binding values would be meaningless
    // without a form to draw fields from).
    // Action / value binding rows for the "Bind Data" panel.
    //
    // These used to live in the element-type OPTIONS panels (Button/Link, Form,
    // Input) — an "Action" select under Button Options, a "Data binding" select
    // under Input Options. That split meant a designer looking for how to wire
    // "Add to Cart" or the search box had to know which of two unrelated panels
    // to open, and the Bind Data panel — the one named after the job — didn't
    // mention them at all. Everything that writes `props._bindings` now lives
    // here, together.
    //
    // Returns '' when the node has no applicable action/value binding.
    //
    // Every action and value here is carried out by a system widget's
    // renderer; on an element that is not inside one the binding would be
    // written and never read. So the rows exist only inside a widget, and
    // each list is narrowed to that widget's type — _getSystemWidgetRegionType()
    // answers '' for "not inside a widget" and a concrete type otherwise
