            text:         [['h1','H1'],['h2','H2'],['h3','H3'],['h4','H4'],['h5','H5'],['h6','H6'],['p',_sdT('Paragraph')],['span','Span'],
                           ['pre',_sdT('Pre (code block)')],['code',_sdT('Code')],['blockquote',_sdT('Blockquote')]],
            interactive:  [['a',_sdT('Link')],['button',_sdT('Button')]],
