        var isRowLikeDiv = (tag === 'div' || tag === 'section' || tag === 'article' || tag === 'main' || tag === 'aside' || tag === 'header' || tag === 'footer' || tag === 'nav') && _hasRowClass(n.props.cssClass || '');
        var isColLikeDiv = (tag === 'div' || tag === 'section' || tag === 'article' || tag === 'main' || tag === 'aside' || tag === 'header' || tag === 'footer' || tag === 'nav') && _hasColClass(n.props.cssClass || '');
        var isModal      = clsList.indexOf('modal') !== -1 && clsList.indexOf('modal-dialog') === -1 && clsList.indexOf('modal-content') === -1;
        var isOffcanvas  = clsList.indexOf('offcanvas') !== -1 && clsList.indexOf('offcanvas-header') === -1 && clsList.indexOf('offcanvas-body') === -1;
