        // Modal dialog: size swap
        document.querySelectorAll('#sd-properties [data-modal-size]').forEach(function(btn) {
            btn.addEventListener('click', function() {
                var newSize = this.getAttribute('data-modal-size');
                var nodeId  = this.getAttribute('data-modal-dlg-id');
                if (!nodeId) return;
                var n = _sdFindNodeForEl(nodeId, null);
                if (!n) return;
                saveState();
                var arr = (n.props.cssClass || '').split(/\s+/).filter(Boolean);
                ['modal-sm','modal-lg','modal-xl','modal-fullscreen'].forEach(function(s) {
                    var i = arr.indexOf(s); if (i !== -1) arr.splice(i, 1);
                });
                if (newSize) arr.push(newSize);
                n.props.cssClass = arr.join(' ');
                var innerEl = getCanvasInnerEl(nodeId);
                if (innerEl) {
                    ['modal-sm','modal-lg','modal-xl','modal-fullscreen'].forEach(function(s) { innerEl.classList.remove(s); });
                    if (newSize) innerEl.classList.add(newSize);
                }
                document.querySelectorAll('#sd-properties [data-modal-size]').forEach(function(b) {
                    b.classList.toggle('active', b.getAttribute('data-modal-size') === newSize);
                });
            });
        });

