            el.addEventListener('change', function() {
                var toggleCls = this.getAttribute('data-modal-cls');
                var nodeId    = this.getAttribute('data-modal-dlg-id');
                if (!nodeId) return;
                var hit = _findNodeAnywhereById(nodeId);
                if (!hit) return;
                var n = hit.node;
                if (hit.sid) _sharedDirty[hit.sid] = true;
                saveState();
                var arr = (n.props.cssClass || '').split(/\s+/).filter(Boolean);
                var idx = arr.indexOf(toggleCls);
                if (this.checked && idx === -1) arr.push(toggleCls);
                if (!this.checked && idx !== -1) arr.splice(idx, 1);
                n.props.cssClass = arr.join(' ');
                var innerEl = getCanvasInnerEl(nodeId);
                if (innerEl) innerEl.classList.toggle(toggleCls, this.checked);
            });
