        // Modal dialog: fullscreen variant swap (breakpoint-based)
        document.querySelectorAll('#sd-properties [data-modal-fullscreen]').forEach(function(sel) {
            sel.addEventListener('change', function() {
                var newFull = this.value;
                var nodeId  = this.getAttribute('data-modal-dlg-id');
                if (!nodeId) return;
                var hit = _findNodeAnywhereById(nodeId);
                if (!hit) return;
                var n = hit.node;
                if (hit.sid) _sharedDirty[hit.sid] = true;
                saveState();
                var allFs = ['modal-fullscreen','modal-fullscreen-sm-down','modal-fullscreen-md-down','modal-fullscreen-lg-down','modal-fullscreen-xl-down','modal-fullscreen-xxl-down'];
                var arr = (n.props.cssClass || '').split(/\s+/).filter(Boolean);
                allFs.forEach(function(s) { var i = arr.indexOf(s); if (i !== -1) arr.splice(i, 1); });
                if (newFull) arr.push(newFull);
                n.props.cssClass = arr.join(' ');
                var innerEl = getCanvasInnerEl(nodeId);
                if (innerEl) {
                    allFs.forEach(function(s) { innerEl.classList.remove(s); });
                    if (newFull) innerEl.classList.add(newFull);
                }
            });
        });

        // Progress bar: value range slider
        document.querySelectorAll('#sd-properties [data-pb-value]').forEach(function(el) {
            var lbl = el.parentElement ? el.parentElement.querySelector('.sd-pb-pct-lbl') : null;
            // Live preview while dragging
            el.addEventListener('input', function() {
                if (lbl) lbl.textContent = this.value + '%';
            });
            // Commit on release
            el.addEventListener('change', function() {
                if (!selectedNode) return;
                saveState();
                var val = parseInt(this.value, 10) || 0;
                var attrs = selectedNode.props._attrs = selectedNode.props._attrs || [];
                var hasStyle = false;
                for (var i = 0; i < attrs.length; i++) {
                    if (attrs[i].name === 'style')         { attrs[i].value = 'width:' + val + '%'; hasStyle = true; }
                    if (attrs[i].name === 'aria-valuenow') { attrs[i].value = String(val); }
                }
                if (!hasStyle) attrs.push({ name: 'style', value: 'width:' + val + '%' });
                if (lbl) lbl.textContent = val + '%';
                renderCanvas();
                renderAttrsPanel();
                renderHtmlTree();
            });
        });

        // Offcanvas: position swap (select dropdown)
        document.querySelectorAll('#sd-properties [data-oc-pos-sel]').forEach(function(sel) {
            sel.addEventListener('change', function() {
                var newPos = this.value;
                var nodeId = this.getAttribute('data-oc-node-id');
                if (!nodeId || !newPos) return;
                var hit = _findNodeAnywhereById(nodeId);
                if (!hit) return;
                var n = hit.node;
                if (hit.sid) _sharedDirty[hit.sid] = true;
                saveState();
                var ALL_POS = ['offcanvas-start','offcanvas-end','offcanvas-top','offcanvas-bottom'];
                var arr = (n.props.cssClass || '').split(/\s+/).filter(Boolean);
                ALL_POS.forEach(function(p) { var i = arr.indexOf(p); if (i !== -1) arr.splice(i, 1); });
                arr.push(newPos);
                n.props.cssClass = arr.join(' ');
                var innerEl = getCanvasInnerEl(nodeId);
                if (innerEl) {
                    ALL_POS.forEach(function(p) { innerEl.classList.remove(p); });
                    innerEl.classList.add(newPos);
                }
            });
        });

