    // ── The hover card ──────────────────────────────────────────────────
    // One card for every palette list, drawn beside the panel so it never
    // covers the list being scanned. It does not take the pointer and goes
    // away on press, drag and scroll: a drag starts exactly as before.
    var _sdPalTip = { el: null, item: null, mute: null, timer: 0, closedAt: 0 };

    function _sdPalTipHTML(item) {
        var it = { type: item.dataset.type || '', label: item.dataset.label || '', extra: {} };
        try { it.extra = item.dataset.extra ? JSON.parse(item.dataset.extra) : {}; } catch (e) { it.extra = {}; }
        var info = _sdPalInfo()[_sdPalKey(it)];
        if (!info) return '';
        var en = _sdEnglishOf(it.label).filter(function (k) { return _sdFold(k) !== _sdFold(it.label); })
            .sort(function (a, b) { return a.length - b.length; })[0] || '';
        var svg = info.v ? _sdPalDrawing(info.v) : '';
        return (svg ? '<div class="sd-pal-tip-preview">' + svg + '</div>' : '') +
            '<div class="sd-pal-tip-head">' +
                (item.dataset.icon ? '<span class="bi ' + esc(item.dataset.icon) + '" aria-hidden="true"></span>' : '') +
                '<span class="sd-pal-tip-name">' + esc(it.label) + '</span>' +
                (en ? '<span class="sd-pal-tip-en">' + esc(en) + '</span>' : '') +
            '</div>' +
            (info.h ? '<code class="sd-pal-tip-code">' + esc(info.h) + '</code>' : '') +
            '<div class="sd-pal-tip-desc">' + esc(info.d) + '</div>';
    }

    function _sdPalTipHide() {
        clearTimeout(_sdPalTip.timer);
        _sdPalTip.item = null;
        var el = _sdPalTip.el;
        if (!el || el.hidden) return;
        el.classList.remove('is-on');
        el.hidden = true;
        _sdPalTip.closedAt = Date.now();
    }

    function _sdPalTipShow(item) {
        if (dragData || !document.body.contains(item)) return;
        var html = _sdPalTipHTML(item);
        if (!html) { _sdPalTipHide(); return; }
        var el = _sdPalTip.el;
        if (!el || !document.body.contains(el)) {
            el = document.createElement('div');
            el.id = 'sd-pal-tip';
            el.className = 'sd-pal-tip';
            el.setAttribute('role', 'tooltip');
            document.body.appendChild(el);
            _sdPalTip.el = el;
        }
        el.innerHTML = html;
        el.hidden = false;
        var r = item.getBoundingClientRect();
        var list = (item.closest('.sd-comp-items-scroll') || item).getBoundingClientRect();
        var w = el.offsetWidth, h = el.offsetHeight;
        var left = list.right + 8;
        if (left + w > window.innerWidth - 8) left = Math.max(8, list.left - w - 8);
        var top = Math.max(8, Math.min(r.top - 8, window.innerHeight - h - 8));
        el.style.left = Math.round(left) + 'px';
        el.style.top = Math.round(top) + 'px';
        requestAnimationFrame(function () { if (!el.hidden) el.classList.add('is-on'); });
    }

    function _sdPalTipWire(root) {
        if (!root || root._sdPalTipWired) return;
        root._sdPalTipWired = true;
        root.addEventListener('mouseover', function (e) {
            var item = e.target && e.target.closest ? e.target.closest('.sd-drag-item') : null;
            if (!item || item === _sdPalTip.item || item === _sdPalTip.mute) return;
            clearTimeout(_sdPalTip.timer);
            _sdPalTip.item = item;
            // While a card is up, or was a moment ago, the next row answers
            // at once: the operator is reading down the list.
            var warm = (_sdPalTip.el && !_sdPalTip.el.hidden) || (Date.now() - _sdPalTip.closedAt < 500);
            _sdPalTip.timer = setTimeout(function () {
                if (_sdPalTip.item === item) _sdPalTipShow(item);
            }, warm ? 60 : 450);
        });
        root.addEventListener('mouseout', function (e) {
            var item = e.target && e.target.closest ? e.target.closest('.sd-drag-item') : null;
            if (!item || (e.relatedTarget && item.contains(e.relatedTarget))) return;
            if (_sdPalTip.mute === item) _sdPalTip.mute = null;
            if (_sdPalTip.item === item) _sdPalTipHide();
        });
        var quiet = function (e) {
            var item = e.target && e.target.closest ? e.target.closest('.sd-drag-item') : null;
            if (item) _sdPalTip.mute = item;
            _sdPalTipHide();
        };
        root.addEventListener('mousedown', quiet, true);
        root.addEventListener('dragstart', quiet, true);
        root.addEventListener('scroll', _sdPalTipHide, true);
    }

    // ── Palette lists ───────────────────────────────────────────────────
    // Three lists draw the same kind of row: the component palette, the
    // ready-made block palette and the recently-used strip. They share the
    // markup and the wiring so a fix to one is a fix to all.

    function _sdPaletteItemHTML(it, extraClass) {
        return '<div class="sd-drag-item' + (extraClass ? ' ' + extraClass : '') + '" draggable="true"' +
            ' data-type="' + it.type + '" data-search="' + _sdPalSearchText(it) + '"' +
            ' data-label="' + (it.label || '').replace(/"/g, '&quot;') + '" data-icon="' + (it.icon || '') + '"' +
            (it.extra && Object.keys(it.extra).length ? " data-extra='" + JSON.stringify(it.extra).replace(/'/g, '&#39;') + "'" : '') + '>' +
            '<span class="sd-drag-icon bi ' + (it.icon || '') + '"></span><span class="sd-drag-label">' + it.label + '</span>' +
            (it.legacy ? _sdLegacyBadge() : '') + '</div>';
    }

    function _sdPaletteCategoriesHTML(cats) {
        var html = '';
        cats.forEach(function (cat) {
            var items = '';
            cat.items.forEach(function (it) { items += _sdPaletteItemHTML(it); });
            html += '<div class="sd-category"><div class="sd-category-header"><span class="bi bi-chevron-down"></span>' + cat.title +
                '</div><div class="sd-category-items">' + items + '</div></div>';
        });
        return html + '<div style="height:24px"></div>';
    }

    // Drag, double-click insert and the collapsible headers. Items already
    // wired are skipped (data-sd-wired), so a list may be passed twice —
    // the recently-used strip is redrawn inside a list that is not.
    function _sdWirePaletteItems(root, recentHost) {
        if (!root) return;

        root.querySelectorAll('.sd-drag-item:not([data-sd-wired])').forEach(function (el) {
            el.setAttribute('data-sd-wired', '1');

            el.addEventListener('dragstart', function (e) {
                var type = this.dataset.type;
                var extra = this.dataset.extra ? JSON.parse(this.dataset.extra) : {};
                dragData = { source: 'palette', type: type, extra: extra, label: this.dataset.label || '', icon: this.dataset.icon || '' };
                _lastDragData = dragData; _lastDragDataTime = Date.now();
                e.dataTransfer.effectAllowed = 'copy';
                e.dataTransfer.setData('text/plain', type);
                // Backup the whole payload on the DataTransfer so the drop
                // handler can rebuild it when a racing `dragend` (Chromium,
                // deep iframe targets) already cleared `dragData`. Palette
                // drags are serialisable; node drags hold a reference.
                try { e.dataTransfer.setData('application/x-pinegrap', JSON.stringify(dragData)); } catch (_) {}
                var ghost = document.createElement('div');
                ghost.className = 'sd-drag-ghost';
                document.body.appendChild(ghost);
                e.dataTransfer.setDragImage(ghost, 0, 0);
                setTimeout(function () { ghost.remove(); }, 0);
            });

            el.addEventListener('dragend', function () {
                // Defer the clear by one tick: Firefox races `dragend` ahead
                // of `drop` on deeply nested targets, and the drop handler
                // clears dragData itself when it handles a drop.
                setTimeout(function () { dragData = null; }, 0);
                if (typeof removeCanvasDropPadding === 'function') removeCanvasDropPadding();
            });

            el.addEventListener('dblclick', function () {
                var type = this.dataset.type;
                var extra = this.dataset.extra ? JSON.parse(this.dataset.extra) : {};
                var hintLabel = this.dataset.label || '';
                var hintIcon  = this.dataset.icon || '';
                var target = selectedNode || tree;
                if (!target) return;
                // The same payload a palette drag carries (see _paletteInsert()).
                var _pd = { source: 'palette', type: type, extra: extra };
                if (!canDrop(_pd, target)) {
                    if (target.children && target.children.length) {
                        for (var i = target.children.length - 1; i >= 0; i--) {
                            if (canDrop(_pd, target.children[i])) { target = target.children[i]; break; }
                        }
                    }
                    if (!canDrop(_pd, target)) target = tree;
                    if (!canDrop(_pd, target)) return;
                }
                saveState();
                var n = createFromPalette(type, extra);
                if (!n) return;
                if (!target.children) target.children = [];
                target.children.push(n);
                selectedNode = n;
                expandAncestors(n, tree);
                // Inserted into a widget's own tree: that tree has to be
                // flushed, and — same rule as a drop — a control that lands
                // inside a custom form widget is a field of it.
                var _dcOwner = (typeof _sdAnyParent === 'function') ? _sdAnyParent(n) : null;
                if (_dcOwner && _dcOwner.sid) _sharedDirty[_dcOwner.sid] = true;
                if (typeof _cfAdoptOnDrop === 'function') _cfAdoptOnDrop(n);
                render();
                _trackRecentComp(type, extra, hintLabel, hintIcon);
                if (recentHost) _renderRecentCompSection(recentHost);
            });
        });

        root.querySelectorAll('.sd-category-header:not([data-sd-wired])').forEach(function (el) {
            el.setAttribute('data-sd-wired', '1');
            el.addEventListener('click', function () { this.closest('.sd-category').classList.toggle('collapsed'); });
        });
    }

    function _sdWirePaletteSearch(input, clear, list) {
        if (!input || !list) return;
        input.addEventListener('input', function () {
            var q = this.value.trim();
            // Every word has to match, in any order: "link a", "button group".
            // A word of one or two letters ("a", "hr", "ul") has to start a
            // word of the item, or "a" would match nearly every row; a
            // longer one may sit anywhere in it, as before.
            var words = _sdFold(q).split(/\s+/).filter(Boolean);
            if (clear) clear.style.display = q ? 'block' : 'none';
            _sdPalTipHide();
            list.querySelectorAll('.sd-drag-item').forEach(function (item) {
                var hay = ' ' + (item.dataset.search || '');
                var hit = words.every(function (w) {
                    return hay.indexOf((w.length < 3 ? ' ' : '') + w) !== -1;
                });
                item.style.display = hit ? '' : 'none';
            });
            list.querySelectorAll('.sd-category').forEach(function (cat) {
                var hasVisible = false;
                cat.querySelectorAll('.sd-drag-item').forEach(function (it) {
                    if (it.style.display !== 'none') hasVisible = true;
                });
                if (q) {
                    cat.style.display = hasVisible ? '' : 'none';
                    cat.classList.remove('collapsed');
                } else {
                    cat.style.display = '';
                }
            });
        });
        if (clear) {
            clear.addEventListener('click', function () {
                input.value = '';
                input.dispatchEvent(new Event('input'));
                input.focus();
            });
        }
    }

    function _renderRecentCompSection(compList) {
        var recent = _getRecentComps();
        // The list is kept per browser, across designs: a custom design does
        // not offer the Bootstrap items another design put there.
        if (!_sdUsesBootstrap()) {
            recent = recent.filter(function (it) {
                return ['component', 'container', 'container-fluid', 'row', 'col'].indexOf(it && it.type) === -1;
            });
        }
        var old = compList.querySelector('#sd-recent-comps-section');
        if (old) old.remove();
        if (!recent.length) return;

        var sec = document.createElement('div');
        sec.id = 'sd-recent-comps-section';
        sec.className = 'sd-category sd-recent-section';

        var items = '';
        recent.forEach(function (it) { items += _sdPaletteItemHTML(it, 'sd-recent-item'); });

        sec.innerHTML = '<div class="sd-category-header"><span class="bi bi-chevron-down"></span>' + esc(_sdT('Recently Used')) + '' +
            '<button type="button" class="sd-recent-clear-btn" title="' + esc(_sdT('Clear')) + '"><span class="bi bi-x-circle"></span></button>' +
            '</div><div class="sd-category-items">' + items + '</div>';

        sec.querySelector('.sd-recent-clear-btn').addEventListener('click', function(e) {
            e.stopPropagation();
            _clearRecentComps();
            sec.remove();
        });

        _sdWirePaletteItems(sec, compList);

        compList.insertBefore(sec, compList.firstChild);
    }

    // ========================= HTML VALIDATION =========================
    // Whether a text prop holds words a reader hears once markup and &nbsp;
    // are taken out.
    function _sdAuditHasText(t) {
        return typeof t === 'string' && t.replace(/<[^>]+>/g, '').replace(/&nbsp;/gi, ' ').trim() !== '';
    }

